{"code":"import bpy
import math

# Perbaiki posisi kamera agar lebih dekat dan fokus ke kabinet
cam = bpy.data.objects['Camera_Main']
cam.location = (1.3, -1.2, 1.1)
cam.rotation_euler = (math.radians(75), 0, math.radians(48))
cam.data.lens = 40

# Set viewport ke camera view
for area in bpy.context.screen.areas:
    if area.type == 'VIEW_3D':
        for space in area.spaces:
            if space.type == 'VIEW_3D':
                space.region_3d.view_perspective = 'CAMERA'
                break

print('Kamera disesuaikan')
